  document.body.style.paddingRight = `${scrollbarWidth}px`; // prevent layout shift
}

function closeModal() {
  document.body.style.overflow = '';
  document.body.style.paddingRight = '';
}
```

This manually calculates the scrollbar width and compensates with padding, so the content doesn't shift when the scrollbar disappears.

---

