  scrollbar-gutter: stable;
}

/* Pure CSS scroll lock when a <dialog> is open */
body:has(dialog[open]) {
  overflow: hidden;
}

/* Prevent scroll chaining from dialog to page (Chrome 144+) */
dialog {
  overscroll-behavior: contain;
}

dialog::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
}
```

